#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cctype>

int insideBraceWordCount = 0, maxWordLen = 0;

int countWordsInString(const std::string& str) {
    std::string s = str;
    // Replace all underscores with spaces
    std::replace(s.begin(), s.end(), '_', ' ');
    // Trim leading and trailing spaces
    size_t start = s.find_first_not_of(' ');
    size_t end = s.find_last_not_of(' ');
    if (start == std::string::npos || end == std::string::npos) {
        return 0;
    }
    s = s.substr(start, end - start + 1);
    // Replace multiple spaces with a single space
    std::string result;
    bool inSpace = false;
    for (char c : s) {
        if (isspace(c)) {
            if (!inSpace) {
                result += ' ';
                inSpace = true;
            }
        } else {
            result += c;
            inSpace = false;
        }
    }
    // Split by space
    int count = 0;
    size_t pos = 0;
    while ((pos = result.find(' ')) != std::string::npos) {
        if (!result.substr(0, pos).empty()) {
            count++;
        }
        result.erase(0, pos + 1);
    }
    if (!result.empty()) {
        count++;
    }
    return count;
}

int main() {
    int totalInputs;
    std::cin >> totalInputs;
    std::string inputStr;
    std::cin >> inputStr;

    std::vector<int> bracePositions;
    bracePositions.push_back(-1);
    for (size_t i = 0; i < inputStr.length(); ++i) {
        if (inputStr[i] == '(' || inputStr[i] == ')') {
            bracePositions.push_back(i);
        }
    }

    int index = 1;
    int totalWords = 0, maxWordLength = 0;
    std::string outsideContent;

    while (index < static_cast<int>(bracePositions.size()) - 1) {
        int start = bracePositions[index];
        int end = bracePositions[index + 1];
        std::string insideBrace = inputStr.substr(start + 1, end - start - 1);
        int countWords = countWordsInString(insideBrace);
        insideBraceWordCount += countWords;
        int prevPos = bracePositions[index - 1];
        outsideContent += "_" + inputStr.substr(prevPos + 1, start - prevPos - 1);
        index += 2;
    }
    int lastPos = bracePositions.back();
    outsideContent += "_" + inputStr.substr(lastPos + 1);

    // Process outsideContent
    std::replace(outsideContent.begin(), outsideContent.end(), '_', ' ');
    // Trim leading and trailing spaces
    size_t start = outsideContent.find_first_not_of(' ');
    size_t end = outsideContent.find_last_not_of(' ');
    if (start != std::string::npos && end != std::string::npos) {
        outsideContent = outsideContent.substr(start, end - start + 1);
    } else {
        outsideContent.clear();
    }
    // Replace multiple spaces with a single space
    std::string cleaned;
    bool inSpace = false;
    for (char c : outsideContent) {
        if (isspace(c)) {
            if (!inSpace) {
                cleaned += ' ';
                inSpace = true;
            }
        } else {
            cleaned += c;
            inSpace = false;
        }
    }
    outsideContent = cleaned;

    // Split outsideWords
    std::istringstream iss(outsideContent);
    std::string w;
    while (iss >> w) {
        if (w.length() > maxWordLen) {
            maxWordLen = w.length();
        }
    }

    std::cout << maxWordLen << " " << insideBraceWordCount;
    return 0;
}
